import org.jsoup.helper.UrlBuilder;
import org.jsoup.helper.DataUtil;
import org.jsoup.Connection;
import org.jsoup.ConnectionBuilder;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.BeforeEach;
import org.junit.Test;

public class UrlBuilderTest {

    private Document document;
    private String inputUrl;

    @BeforeEach
    public void setup() {
        URL url = new URL("http://example.com");
        document = Jsoup.parse(url.toString());
        inputUrl = url.toString();
    }

    @Test
    public void test_build_url_without_params() throws UnsupportedEncodingException {
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL result = urlBuilder.build();
        assertNotNull(result);
    }

    @Test
    public void test_build_url_with_params() throws UnsupportedEncodingException {
        String[] params = {"key1=value1", "key2=value2"};
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com?param1=value1&param2=value2"));
        URL result = urlBuilder.build();
        assertNotNull(result);
    }

    @Test
    public void test_build_url_with_params_from_keyval() throws UnsupportedEncodingException {
        String[] params = {"key1=value1", "key2=value2"};
        UrlBuilder urlBuilder = new UrlBuilder(new Connection(new URL("http://example.com?param1=value1&param2=value2"), Connection.Builder.newConnection()));
        urlBuilder.appendKeyVal(new java.util.HashMap<String, String>() {{
            put("key1", "value1");
            put("key2", "value2");
        }});
        Url result = urlBuilder.build();
        assertNotNull(result);
    }

    @Test
    public void test_append_key_val_with_url() throws UnsupportedEncodingException {
        String[] params = {"key1=value1", "key2=value2"};
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com"));
        urlBuilder.appendKeyVal(params);
        Document result = document;
        for (String param : params) {
            assertEquals(param, result.selectFirst("input[name^=param]").attr("value"));
        }
    }

    @Test
    public void test_append_key_val_with_keyval() throws UnsupportedEncodingException {
        String[] params = {"key1=value1", "key2=value2"};
        UrlBuilder urlBuilder = new UrlBuilder(new Connection(new URL("http://example.com"), Connection.Builder.newConnection()));
        urlBuilder.appendKeyVal(params);
        Document result = document;
        for (String param : params) {
            assertEquals(param, result.selectFirst("input[name^=param]").attr("value"));
        }
    }

    @Test
    public void test_build_url_with_invalid_keyval() throws UnsupportedEncodingException {
        String[] params = {"key1=value1", "key2=value2"};
        UrlBuilder urlBuilder = new UrlBuilder(new Connection(new URL("http://example.com"), Connection.Builder.newConnection()));
        urlBuilder.appendKeyVal(null);
        Document result = document;
        assertNull(result.selectFirst("input[name^=param]"));
    }
}
